function barkPaint(m,key){m.side=THREE.DoubleSide;m.onBeforeCompile=sh=>{
 sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vWb,vNb;').replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvWb=(modelMatrix*vec4(transformed,1.)).xyz;vNb=normalize(mat3(modelMatrix)*objectNormal);');
 sh.fragmentShader=sh.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vWb,vNb;'+WC_GLSL)
 .replace('#include <map_fragment>',`#include <map_fragment>
 {vec2 uv=vMapUv;
  // long vertical pigment strokes that follow the wood, wet-edge pooling, granulation, mossy tops, cool lichen patches
  float s1=wcN(vec2(uv.x*7.,uv.y*.9));float s2=wcN(vec2(uv.x*15.+3.,uv.y*2.1));float str=s1*.65+s2*.35;
  float gran=wcN(vWb.xz*14.+vWb.y*9.)*.5+wcN(vWb.xy*31.)*.5;
  vec3 dark=vec3(.2,.16,.13),mid=vec3(.42,.33,.26),light=vec3(.62,.52,.42),lichen=vec3(.5,.52,.38);
  vec3 c=mix(dark,mid,smoothstep(.25,.6,str));c=mix(c,light,smoothstep(.62,.85,str)*.8);
  float lp=wcF(vWb.xz*.6+vWb.y*.35);c=mix(c,lichen,smoothstep(.55,.7,lp)*.45);
  float edge=smoothstep(.56,.6,str)*(1.-smoothstep(.6,.66,str));c*=1.-edge*.25;
  float moss=smoothstep(.35,.8,vNb.y)*smoothstep(.35,.6,wcF(vWb.xz*1.3+vWb.y*.7));c=mix(c,vec3(.2,.36,.26),moss*.85);float drip=smoothstep(.62,.8,wcN(vec2(uv.x*11.,uv.y*.35+3.)))*smoothstep(.3,.7,wcF(vWb.xz*.8));c=mix(c,vec3(.22,.34,.25),drip*.55);
  c*=.9+.2*gran;float lum=dot(diffuseColor.rgb,vec3(.333));
  diffuseColor.rgb=c*mix(1.,lum*2.,.18);}`)};
 m.customProgramCacheKey=()=>'barkPaint'+key;m.needsUpdate=true;return m}
const barkTex=(()=>{const [c,x]=cnv(256,512);x.fillStyle='#5a4532';x.fillRect(0,0,256,512);
 for(let i=0;i<900;i++){const px=rng()*256,w=2+rng()*7,l=20+rng()*140,py=rng()*512;const s=rng();x.fillStyle=s<.5?`rgba(30,22,14,${.25+rng()*.4})`:`rgba(140,118,90,${.12+rng()*.18})`;x.fillRect(px,py,w,l);x.fillRect(px-256,py,w,l);x.fillRect(px,py-512,w,l)}
 for(let i=0;i<70;i++){x.fillStyle=`rgba(20,14,8,${.3+rng()*.3})`;x.fillRect(rng()*256,rng()*512,8+rng()*30,2)}
 for(let i=0;i<260;i++){x.fillStyle=`rgba(${90+rng()*30|0},${110+rng()*30|0},50,${.12+rng()*.18})`;x.beginPath();x.arc(rng()*256,rng()*512,2+rng()*8,0,7);x.fill()}
 return texFrom(c,[2,6])})();
