 eyes.material.emissive=new THREE.Color(.55,.55,.55);eyes.material.emissiveMap=eyes.material.map;eyes.material.roughness=.25;
 if(cards){cards.material=cards.material.clone();cards.material.depthWrite=false;cards.material.alphaTest=.02;if(kind==='tink')cards.material.map=lightCards(cards.material.map);cards.castShadow=false}
