function refSample(arr,t){const n=arr.length,x=((t%1)+1)%1*n,i=Math.floor(x),f=x-i,a=arr[i%n],b=arr[(i+1)%n];return Array.isArray(a)?a.map((v,k)=>v+(b[k]-v)*f):a+(b-a)*f}
function refFoot(r,id,lp,S,H){const [zn,yn,fold]=refSample(r.legs[id],lp);return [zn*S,yn*H,yn,fold]}
function gaitFoot(p,D,S,H){if(p<D){const s=p/D;return [S*.5-S*s,0,0,s>.85?(s-.85)/.15*.35:0]}const s=(p-D)/(1-D);const e=s*s*(3-2*s);return [-S*.5+S*e,H*Math.pow(Math.sin(Math.PI*s),.8),Math.sin(Math.PI*s),Math.sin(Math.PI*Math.min(1,s/.55))*(s<.55?1:0)]}
function rot2(x,y,a){const c=Math.cos(a),s=Math.sin(a);return [x*c-y*s,x*s+y*c]}

