  for(const [a,b2,tab] of RUNB.body)point(nb.B[a],nb.B[b2],refSample(tab,ph),wG);
  for(const id of ['LF','RF','LH','RH']){const segs=REFD.gallop.legs[id],ch=nb.legs[id];const side=id[0]==='L'?1:-1;for(let k=0;k<4;k++){const v=refSample(segs[k],ph);point(ch[k],ch[k+1],[v[0],v[1],v[2]*side],wG)}}
