function detectRadius(){if(P.mode==='climb')return 3;if(P.sit>.5)return 2.2;if(P.mode==='air')return P.pouncing?2.6:4;const s=P.speed;if(AP.stalk>.5)return s>.05?1.6:1.1;if(s<.05)return 2.6;if(s<1.3)return 4.2;if(s<T.run+.5)return 6.5;return 9}
