function updateSquirrels(dt,time){keepCrittersNear(dt);
 const R=detectRadius();
 for(const s of squirrels){s.timer+=dt;if(s.kind==='robin'){updateRobin(s,dt,time,R);continue}const dx=s.x-P.pos.x,dz=s.z-P.pos.z,dCat=Math.hypot(dx,dz);if(s.home&&s.home.gone&&s.state!=='treed'&&s.state!=='climb'&&s.state!=='descend'){/* its tree was removed in the editor: adopt the nearest standing tree */let bt=null,bd=1e9;for(const t2 of trees){if(t2.gone||!(t2.climbTop>t2.g))continue;const d2=Math.hypot(t2.x-s.x,t2.z-s.z);if(d2<bd){bd=d2;bt=t2}}if(bt)s.home=bt}const t=s.home;let speed=0,hopH=.035,bodyPitch=0,tailA=.5,curl=3.2,flick=0;
  if(s.state==='caught'){window.__carryAdd&&window.__carryAdd(s.g,s.co||(s.co={f:.08,u:-.07,yaw:Math.PI/2}));s.body.rotation.set(0,0,.6+Math.sin(time*10)*.15);sqAnim(s,'move',.7);continue}
  if(s.state==='forage'||s.state==='nibble'){
   if(dCat<R*.55){s.state='startle';s.timer=0}else if(dCat<R){s.state='alert';s.timer=0}
   else if(s.state==='forage'){if(!s.tx||s.timer>6){const a=Math.random()*6.28,r=t.r+1+Math.random()*6;s.tx=t.x+Math.cos(a)*r;s.tz=t.z+Math.sin(a)*r;s.timer=0}
    const ddx=s.tx-s.x,ddz=s.tz-s.z,dd=Math.hypot(ddx,ddz);if(dd<.2){s.state='nibble';s.timer=0;s.tx=0}else{s.yaw=Math.atan2(ddx,ddz);speed=1.1}}
   else if(s.timer>2+Math.random()*3){s.state='forage';s.timer=0}
   s.talkT=(s.talkT??8+Math.random()*20)-dt;if(s.talkT<=0){s.talkT=18+Math.random()*25;sfx('squirrel_talking',{at:new V3(s.x,s.y,s.z),vol:.55,maxDist:14})}}
  else if(s.state==='alert'){bodyPitch=-.9;tailA=1.2;curl=2.4;flick=1;s.yaw=damp(s.yaw,s.yaw+angDiff(s.yaw,Math.atan2(-dx,-dz)),6,dt);if(dCat<R*.6||(s.timer>.6&&dCat<R*1.1)){s.state='startle';s.timer=0}else if(s.timer>2.5){s.state='forage';s.timer=0}}
  else if(s.state==='startle'){if(s.timer<dt*1.5)sfx('squirrel_chirping',{at:new V3(s.x,s.y,s.z),vol:.7,rate:1+Math.random()*.15});if(s.timer>.3){s.state='flee';s.timer=0}}
  else if(s.state==='flee'||s.state==='dazed'){
   const tx=t.x-s.x,tz=t.z-s.z,td=Math.hypot(tx,tz);let ax=tx/td,az=tz/td;const awayx=dx/(dCat||1),awayz=dz/(dCat||1);
   const toward=-(ax*awayx+az*awayz);if(toward>.5&&dCat<3){ax=awayx;az=awayz}
   let yaw=Math.atan2(ax,az);if(dCat<2.4)yaw+=Math.sin(time*7+s.t0)*.6;s.yaw=yaw;speed=s.state==='dazed'?3.6:4.8;hopH=.09;tailA=.15;curl=.9;
   if(td<t.r+.25){s.state='climb';s.timer=0;s.ang=Math.atan2(s.z-t.z,s.x-t.x);s.cy=heightAt(s.x,s.z);s.goal=t.g+2.2+Math.random()*2.3}
   if(s.state==='flee'&&s.timer>7&&dCat>R*1.5){s.state='forage';s.timer=0}}
  if(s.state==='climb'||s.state==='treed'||s.state==='descend'){
   if(s.state==='climb'){s.cy+=3.2*dt*(.35+1.3*Math.max(0,Math.sin(s.timer*Math.PI*2*3.2)));if(s.cy>=s.goal){s.state='treed';s.timer=0}}
   else if(s.state==='treed'){const ca=Math.atan2(-dz,-dx);s.ang+=angDiff(s.ang,ca+Math.PI)*dt*.4;s.chatT=(s.chatT??1+Math.random()*2)-dt;if(s.chatT<=0){s.chatT=6+Math.random()*7;sfx('squirrel_teasing',{at:new V3(s.x,s.y,s.z),vol:.7,rate:.95+Math.random()*.1,maxDist:26})}if(s.timer>6&&dCat>7){s.state='descend'}}
   else if(s.state==='descend'){s.cy-=1.8*dt;if(s.cy<=t.g+.05){s.state='forage';s.timer=0;s.tx=0;const n2=new V3(Math.cos(s.ang),0,Math.sin(s.ang));s.x=t.x+n2.x*(t.r+.25);s.z=t.z+n2.z*(t.r+.25);s.y=heightAt(s.x,s.z);s.g.quaternion.identity()}}
   if(s.state!=='forage'){const n=new V3(Math.cos(s.ang),0,Math.sin(s.ang));s.x=t.x+n.x*(t.r+.07);s.z=t.z+n.z*(t.r+.07);s.y=s.cy;
    const fwd=new V3(0,s.state==='treed'||s.state==='descend'?-1:1,0);const x=new V3().crossVectors(n,fwd);_mtx.makeBasis(x,n,fwd);s.g.quaternion.slerp(new Q().setFromRotationMatrix(_mtx),s.state==='climb'&&s.timer<.15?1:1-Math.exp(-14*dt));
    s.g.position.set(s.x,s.y,s.z);s.body.position.y=.015;s.body.rotation.x=.16;s.body.scale.set(1,1,1);sqAnim(s,'move',s.state==='climb'?1.7:s.state==='descend'?1.1:.06);
    poseSqTail(s,s.state==='treed'?1.2:.3,s.state==='treed'?2.6:1.2,s.state==='treed'?1.2:.3,time);s.head.rotation.x=s.state==='treed'?-.6:0;continue}}
  // ground motion
  if(speed>0){const nx=s.x+Math.sin(s.yaw)*speed*dt,nz=s.z+Math.cos(s.yaw)*speed*dt;s.x=nx;s.z=nz;s.hop+=dt*(speed>2?6.5:4.2)}else s.hop=0;
  s.y=damp(s.y,Math.max(groundAt(s.x,s.z,s.y+.5),waterLevelAt(s.x,s.z)),18,dt);
  s.g.quaternion.setFromAxisAngle(AY,s.yaw);s.g.position.set(s.x,s.y,s.z);
  s.body.position.y=s.state==='startle'?Math.sin(Math.min(1,s.timer/.3)*Math.PI)*.06:0;s.body.rotation.x=0;s.body.scale.set(1,1,1);
  if(speed>0)sqAnim(s,'move',clamp(speed/2.2,.6,2.3));else sqAnim(s,'idle',s.state==='startle'?2:s.state==='alert'?1.4:1);
  s.head.rotation.x=s.state==='nibble'?.45+Math.sin(time*14)*.12:s.state==='alert'?.7:0;
  poseSqTail(s,tailA,curl,flick+(s.state==='nibble'?.3:0),time)}
}

