 window.__plantBean=()=>{const b=BN();const c=spot();if(b.st!==2||!c||dTo(c.x,c.z)>=2.8)return false;try{window.__dig(2.6,c.x,c.z)}catch(e){}b.st=3;b.el=0;b.ch=0;b.last=weather;saveQ();try{sfx('chime',{vol:.5})}catch(e){}try{window.__TUT&&window.__TUT.hide()}catch(e){}story('Tink tucks the bean into the soft earth…','and the glade settles down to sleep',5200);return true};
 addEventListener('keydown',e=>{if(e.code==='KeyE'&&started&&!window.__EDITING&&window.__plantBean&&window.__plantBean()){e.preventDefault();e.stopImmediatePropagation()}},true);
 /* ---- DOM */
 /* Build 346: each quest step has a little box that ticks when it's done, then the next step fades in */const BOX='<svg class="dm bx" width="13" height="13" viewBox="0 0 12 12" aria-hidden="true"><rect x="1.2" y="1.2" width="9.6" height="9.6" rx="2.2" fill="rgba(255,255,255,.16)" stroke="#ffffff" stroke-width="1.3"/><path class="ck" d="M3 6.2 L5.1 8.3 L9.2 3.4" fill="none" stroke="#ffffff" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';const D='<svg class="dm" width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M6 1 L11 6 L6 11 L1 6 Z" fill="rgba(255,255,255,.25)" stroke="#ffffff" stroke-width="1.3"/></svg>';
