 /* Build 359: the map is a round watercolour vignette: a thin white frame, a soft paper edge, a plain white N and a white arrow for Tink */const MAPRING='<svg width="192" height="192" viewBox="0 0 192 192" aria-hidden="true"><defs><radialGradient id="adFog" cx=".5" cy=".5" r=".5"><stop offset=".62" stop-color="#f4ead6" stop-opacity="0"/><stop offset=".92" stop-color="#f4ead6" stop-opacity=".14"/><stop offset="1" stop-color="#f4ead6" stop-opacity=".3"/></radialGradient></defs><circle cx="96" cy="96" r="80" fill="url(#adFog)"/><circle cx="96" cy="96" r="80.5" fill="none" stroke="rgba(255,255,255,.9)" stroke-width="1.6"/><circle cx="96" cy="96" r="86" fill="none" stroke="rgba(255,255,255,.35)" stroke-width="1"/><g id="ad-n"><circle r="8.5" fill="rgba(20,30,36,.45)"/><text x="0" y="4" text-anchor="middle" font-family="Montserrat, sans-serif" font-size="11" font-weight="600" fill="#fff">N</text></g><g id="ad-ar" transform="translate(96 96)" style="filter:drop-shadow(0 1px 3px rgba(0,0,0,.6))"><path d="M0 -10 L7 7.5 L0 3.8 L-7 7.5 Z" fill="#fff" stroke="rgba(30,40,50,.35)" stroke-width=".8"/></g></svg>';
 const adv=document.createElement('div');adv.id='adv';adv.setAttribute('aria-hidden','true');
