 /* quest journal */
 const qm=document.createElement('div');qm.id='qmenu';qm.hidden=true;qm.setAttribute('role','dialog');qm.setAttribute('aria-label','Quest journal');
 qm.innerHTML='<div class="qm-in"><div class="qm-h"><h2>Quest Journal</h2><button class="qm-x" id="qmX">Close · J</button></div><div class="qm-cols"><section><h3>JACK&rsquo;S STORY</h3><ol id="qmMain"></ol></section><section><h3>SIDE QUESTS</h3><ul id="qmSide"></ul></section></div><div class="qm-f">Pick a side quest to follow it under the main story.</div></div>';
 document.body.appendChild(qm);
 const curMain=()=>{for(const q of MAIN){if(Q.done[q.id])continue;if(q.unlock&&!q.unlock())continue;return q}return null};window.__QAPI={curMain,place,BN,spot,Q,saveQ,MAIN};if((Q.p.sv||0)<364){Q.p.sv=364;for(const q of MAIN)if(!Q.done[q.id])delete Q.step[q.id]}/* Build 367: a beanstalk climbed before the leaf could be given is climbed again for it */setTimeout(()=>{try{if(Q.done.bean&&!GOT('leaf')){delete Q.done.bean;delete Q.step.bean;if(Q.p.dir&&Q.p.dir.tu)delete Q.p.dir.tu.bean;saveQ()}}catch(e){}},4000);
 const renderMenu=()=>{const cm=curMain();$('qmMain').innerHTML=MAIN.map(q=>{const d=!!Q.done[q.id],u=!q.unlock||q.unlock()||d;if(!u)return '<li class="lock"><b>???</b><span>Keep exploring…</span></li>';let st=q.steps[Math.min(Q.step[q.id]||0,q.steps.length-1)][0];if(typeof st==='function')st=st();const LQ=d&&window.__STORY&&window.__STORY.LINES&&window.__STORY.LINES[q.id];return '<li class="'+(d?'done':cm===q?'cur':'')+'"><b>'+(d?'✓ ':'')+q.title+'</b><span>'+(d?'Complete':st)+'</span>'+(LQ?'<i class="qq">“'+LQ.map(l=>l[0]).join(' ')+'” — Jack</i>':'')+'</li>'}).join('');
  $('qmSide').innerHTML=SIDE.map(s=>{const d=!!Q.done[s.id],u=!!Q.unl[s.id];if(!u)return '<li class="lock"><b>???</b><span>Unlocks as you explore</span></li>';const pr=s.prog();return '<li class="'+(d?'done':Q.track===s.id?'cur':'')+'"><b>'+(d?'✓ ':'')+s.title+'</b><span>'+s.desc+(pr[1]>1?' · '+pr[0]+'/'+pr[1]:'')+'</span>'+(d?'':'<button data-q="'+s.id+'" aria-pressed="'+(Q.track===s.id)+'">'+(Q.track===s.id?'Following':'Follow')+'</button>')+'</li>'}).join('');
  for(const b of $('qmSide').querySelectorAll('button'))b.onclick=e=>{e.stopPropagation();Q.track=Q.track===b.dataset.q?null:b.dataset.q;saveQ();renderMenu();draw()}};
 const QUESTS=window.__QUESTS={isOpen:()=>!qm.hidden,menu:(on)=>{if(on===undefined)on=qm.hidden;if(on&&(!started||window.__EDITING))return;if(on){renderMenu();qm.hidden=false;window.__pause=true;try{document.exitPointerLock()}catch(e){}}else if(!qm.hidden){qm.hidden=true;window.__pause=false;try{tryLock()}catch(e){}}}};
 $('qmX').onclick=e=>{e.stopPropagation();QUESTS.menu(false)};qm.addEventListener('click',e=>{if(e.target===qm)QUESTS.menu(false)});
 /* cards slide in one at a time */
 const cards=[];let cardT=0;/* Build 347: room to breathe - one story moment at a time (quest cards, chapter titles, Jack's words, gifts), each followed by a pause before the next */const CALM=window.__CALM||(window.__CALM={until:0,busy(){return performance.now()<this.until},hold(sec,gap=1.8){this.until=Math.max(this.until,performance.now()+(sec+gap)*1000)}});const card=(h,t,s)=>{cards.push([h,t,s||''])};
 const cardTick=dt=>{const el=$('ad-card');if(cardT>0){cardT-=dt;if(cardT<=1.4&&el.classList.contains('in'))el.classList.remove('in');return}if(!cards.length||!adv.classList.contains('on')||CALM.busy()||(window.__JACK&&window.__JACK.showing)||(window.__STORY&&window.__STORY.busy&&window.__STORY.busy()))return;/* Build 363: Jack's words come first; quest cards wait for him */const [h,t,s]=cards.shift();$('ad-ch').textContent=h;$('ad-ct').textContent=t;$('ad-cs').textContent=s;el.classList.add('in');cardT=6.5;CALM.hold(6.5);try{sfx('chime',{vol:.35})}catch(e){}};
 /* minimap: a painted map of the whole forest, made once, then turned and slid under Tink */
 let base=null;const MS=2;/* base pixels per metre */
 const buildMap=()=>{const N=Math.round(WORLD*MS);const c=document.createElement('canvas');c.width=c.height=N;const x=c.getContext('2d');const im=x.createImageData(N,N);const mc=grassU.uMask.value&&grassU.uMask.value.image;let md=null,W2P=1;try{md=mc.getContext('2d').getImageData(0,0,mc.width,mc.height).data;W2P=mc.width/WORLD}catch(e){}
  for(let j=0;j<N;j++)for(let i=0;i<N;i++){const wx=i/MS-WORLD/2,wz=j/MS-WORLD/2;let r=118,g=150,b=104;const n=(Math.sin(wx*.35)+Math.sin(wz*.31+wx*.12)+Math.sin(wx*.9+wz*.7)*.5)*5;r+=n;g+=n*1.3;b+=n*.6;
   if(md){const px=Math.round((wx+WORLD/2)*W2P),pz=Math.round((wz+WORLD/2)*W2P);if(px>=0&&pz>=0&&px<mc.width&&pz<mc.height&&md[(pz*mc.width+px)*4]<120){r=226;g=210;b=170}}
   let sg=99;try{sg=streamGap(wx,wz)}catch(e){}if(sg<0){r=140;g=190;b=214;if(sg<-.6){r=158;g=204;b=224}}else if(sg<.6){r=r*.8+30;g=g*.85+30;b=b*.8+40}
   const k=(j*N+i)*4;im.data[k]=r;im.data[k+1]=g;im.data[k+2]=b;im.data[k+3]=255}
  x.putImageData(im,0,0);
  for(const t of (typeof trees!=='undefined'?trees:[])){if(t.gone)continue;const cx=(t.x+WORLD/2)*MS,cz=(t.z+WORLD/2)*MS;const R=Math.max(2.2,(t.r||.4)*5)*MS;const gr=x.createRadialGradient(cx-R*.3,cz-R*.3,R*.1,cx,cz,R);gr.addColorStop(0,'#8fb879');gr.addColorStop(1,'#4d7553');x.fillStyle=gr;x.beginPath();x.arc(cx,cz,R,0,6.283);x.fill();x.strokeStyle='rgba(40,60,44,.35)';x.lineWidth=1;x.stroke()}
  base=c};
