  'Moving truck':()=>{/* retired */return null;if(!LAZY.truck)return null;const o=fitClone(LAZY.truck.scene,5.6,'xz');o.traverse(m=>{if(m.isMesh){m.castShadow=m.receiveShadow=true;m.material=m.material.clone();m.material.userData.tag='truck'}});o.userData.colCap=150000;return o},
