  'Ghibli tree 1':()=>ghibliTree(0),'Ghibli tree 2':()=>ghibliTree(1),'Ghibli tree 3':()=>ghibliTree(2),'Ghibli tree 4':()=>ghibliTree(3),'Ghibli tree 5':()=>ghibliTree(4),'Ghibli bush 1':()=>ghibliTree(5),'Ghibli bush 2':()=>ghibliTree(6),
