 /* single pieces out of model packs: each lantern or tool on its own */
 const addVariants=(label,gl,grp,size,by,tag)=>{if(!gl)return;let vs;try{vs=kit(gl.scene,grp)}catch(e){return}let packK=0;if(by==='pack'){const bb=new THREE.Box3().setFromObject(gl.scene);packK=size/Math.max(bb.max.x-bb.min.x,bb.max.z-bb.min.z)}
  vs.forEach((v,i)=>{if(v.h<1e-5)return;KINDS[label+' '+(i+1)]=()=>{const g=new THREE.Group();for(const pt of v.parts){const m=new THREE.Mesh(pt.g,tintMat(pt.mat.clone(),tag));m.castShadow=m.receiveShadow=true;g.add(m)}g.scale.setScalar(by==='pack'?packK:size/v.h);return g}})};
 addVariants('Stone lantern',LANTG,o=>o.name.split('_')[0],1.2,'h','lantern');addVariants('Paper lantern',PLANTG,o=>o.uuid,.62,'h','paper');addVariants('Farm tool',TOOLG,o=>o.uuid,2.6,'pack','tools');
 const HIDDEN_KINDS=new Set(['Stone lanterns','Paper lanterns','Fern','Toadstools','Big leaf','Moving truck','Stone bridge (flat)','Ghibli tree 1','Ghibli tree 2','Ghibli tree 3','Ghibli tree 4','Ghibli tree 5','Ghibli bush 1','Ghibli bush 2']);/* kept so older saved pieces still load */
 /* the painted look for everything you can place */
 {const grpOf=(geo,mat,h)=>{const m=new THREE.Mesh(geo,mat);m.castShadow=m.receiveShadow=true;geo.computeBoundingBox();const b=geo.boundingBox;m.position.set(-(b.min.x+b.max.x)/2,-b.min.y,-(b.min.z+b.max.z)/2);const g=new THREE.Group();g.add(m);if(h){const k=h/Math.max(1e-3,b.max.y-b.min.y);m.scale.setScalar(k);m.position.multiplyScalar(k)}return g};
  /* pieces that used to be sized on the outer group (saved matrices include that size): keep the same convention */const outerFit=(geo,mat,len)=>{const g=grpOf(geo,mat,0);const b=geo.boundingBox;g.scale.setScalar(len/Math.max(1e-3,b.max.x-b.min.x,b.max.z-b.min.z));return g};
  /* Build 193: placed stones settle into the ground too (about half buried) */const sinkRock=(g,f)=>{const m=g.children[0];if(m&&m.geometry){const b=m.geometry.boundingBox;m.position.y-=f*(b.max.y-b.min.y)*m.scale.y}return g};
  let BV=null,FV=null;const bushV=()=>BV||(BV=BUSH?bushClump(kit(BUSH.scene,o=>o.name.slice(0,6))):[]);const flowV=()=>FV||(FV=FLOW?flowerDots(kit(FLOW.scene,o=>o.uuid)):[]);
  const fromVariant=(v,h,tag)=>{if(!v)return null;const g=new THREE.Group(),inner=new THREE.Group();g.add(inner);for(const pt of v.parts){const m=new THREE.Mesh(pt.g,windMat(tintMat(pt.mat.clone(),tag),.06));m.castShadow=m.receiveShadow=true;inner.add(m)}inner.scale.setScalar(h/Math.max(1e-3,v.h));return g};
  Object.assign(KINDS,{
   'River stone':()=>{let geo=null;RIVR.scene.traverse(o=>{if(o.isMesh&&!geo)geo=o});return geo?sinkRock(outerFit(paintRock(baseGeo(geo),1,31),stoneMat,.9),.28):null},
   'Mossy rock':()=>{const GRK_M=GROCKG&&GROCKG.scene.getObjectByProperty('isMesh',true);if(GRK_M)return sinkRock(grpOf((()=>{const g=baseGeo(GRK_M);if(!g.attributes.uv)g.setAttribute('uv',new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count*2),2));g.computeBoundingBox();g.computeBoundingSphere();return g})(),stoneMat,.95),.32);const mm=RMOSS&&RMOSS.scene.getObjectByProperty('isMesh',true);return mm?sinkRock(grpOf(paintRock(baseGeo(mm),2,3),stoneMat,.95),.32):null},
   'Boulder':()=>ARCHGEO.Rock_6?sinkRock(outerFit(paintRock(ARCHGEO.Rock_6,2,9),stoneMat,1.2),.32):null,
   'Wheat':()=>grpOf(WHEAT_TUFT(),tuftMat('wheat'),.95),
   'Beet patch':()=>{const g=new THREE.Group();const geo=BEET_TUFT(),mt=tuftMat('veg');for(let i=0;i<9;i++){const m=new THREE.Mesh(geo,mt);m.position.set((i%3-1)*.35,0,(Math.floor(i/3)-1)*.35);m.rotation.y=i*1.7;m.castShadow=true;g.add(m)}return g},
   'Bush':()=>fromVariant(bushV()[0],1,'bush'),
   'Flowers':()=>fromVariant(flowV()[0],.5,'flow'),
   'Stone bridge (flat)':()=>archPiece('Rock_3',6),
   'Ghibli tree 1':()=>KINDS['Green tree'](),'Ghibli tree 2':()=>KINDS['Cherry tree'](),'Ghibli tree 3':()=>KINDS['Green tree'](),'Ghibli tree 4':()=>KINDS['Cherry tree'](),'Ghibli tree 5':()=>KINDS['Green tree'](),
   'Ghibli bush 1':()=>KINDS['Bush'](),'Ghibli bush 2':()=>KINDS['Bush']()})}
 /* friendly names in the editor's lists (saved pieces keep their old keys, so nothing breaks) */
 const KIND_LABEL={'Cherry tree':'Cherry tree (blossom)','Green tree':'Green tree','River stone':'Small rounded stone','Mossy rock':'Medium mossy rock','Boulder':'Large boulder','Stepping stone':'Flat stepping stone','Stone bridge (curved)':'Stone bridge','Stone arch':'Stone arch','Wheat':'Wheat tuft','Beet patch':'Beetroot patch','Bush':'Round bush','Flowers':'Flower tuft','Barrel':'Barrel','Cushion':'Cushion','Washing line':'Washing line','Wooden fence 1':'Wooden fence (straight)','Wooden fence 2':'Wooden fence (tilted rail)','Wooden fence 3':'Wooden fence (slipped rail)','Wooden fence 4':'Wooden fence (leaning post)','Wooden fence 5':'Wooden fence (rail missing)','Wooden fence 6':'Wooden fence (crooked)','Well':'Well','Forest spirit':'Forest spirit'};
 const lantSorted=Object.keys(KINDS).filter(k=>/^Stone lantern \d/.test(k));const sizeWords=['Small','Medium','Tall','Tallest','Grand'];lantSorted.forEach((k,i)=>{KIND_LABEL[k]=(sizeWords[i]||('#'+(i+1)))+' stone lantern'});
 Object.keys(KINDS).filter(k=>/^Paper lantern \d/.test(k)).forEach((k,i)=>{KIND_LABEL[k]='Paper lantern '+['(round)','(tall)','(small)','(wide)','(long)'][i%5]});
 Object.keys(KINDS).filter(k=>/^Farm tool \d/.test(k)).forEach((k,i)=>{KIND_LABEL[k]='Farm tool '+(i+1)});

 /* the rustic garden fence: one low-poly panel (two posts, two rails) taken apart and put back together six ways, so a run of panels looks hand-built (a rail tilted, slipped, missing, a post leaning); each piece of wood painted its own shade, mossy and dark where it meets the ground */
 let FENCEV=null,FENCEM=null;
 function fenceKind(i){if(!FENCEG)return null;if(!FENCEV){try{FENCEV=buildFence()}catch(e){console.warn('fence',e);FENCEV=[]}}const geo=FENCEV[i%Math.max(1,FENCEV.length)];if(!geo)return null;const m=new THREE.Mesh(geo,FENCEM);m.castShadow=m.receiveShadow=true;const g=new THREE.Group();g.add(m);return g}
 function buildFence(){const sc=FENCEG.scene;sc.updateMatrixWorld(true);let src=null,mat0=null;sc.traverse(o=>{if(o.isMesh&&!src){src=o.geometry.clone().applyMatrix4(o.matrixWorld);mat0=o.material}});if(!src)return [];
  const g=src.index?src.toNonIndexed():src;g.computeBoundingBox();const bb=g.boundingBox;const k=2.15/(bb.max.x-bb.min.x);g.translate(-(bb.min.x+bb.max.x)/2,-bb.min.y,-(bb.min.z+bb.max.z)/2);g.scale(k,k,k);
  const P=g.attributes.position,N=g.attributes.normal,UV=g.attributes.uv,nt=P.count/3;
  // split into the separate pieces of wood: triangles that share a corner belong to the same piece
  const par=new Int32Array(nt).map((_,i)=>i);const f=x=>{while(par[x]!==x){par[x]=par[par[x]];x=par[x]}return x};const seen=new Map();
  for(let t=0;t<nt;t++)for(let c=0;c<3;c++){const v=t*3+c;const key=Math.round(P.getX(v)*500)+','+Math.round(P.getY(v)*500)+','+Math.round(P.getZ(v)*500);if(seen.has(key))par[f(t)]=f(seen.get(key));else seen.set(key,t)}
  const groups=new Map();for(let t=0;t<nt;t++){const r=f(t);if(!groups.has(r))groups.set(r,[]);groups.get(r).push(t)}
  const parts=[];for(const tris of groups.values()){const b=new THREE.Box3();const v=new V3();for(const t of tris)for(let c=0;c<3;c++)b.expandByPoint(v.fromBufferAttribute(P,t*3+c));const sz=b.getSize(new V3());parts.push({tris,b,rail:sz.x>sz.y})}
  const posts=parts.filter(q=>!q.rail).sort((a,b)=>a.b.min.x-b.b.min.x),rails=parts.filter(q=>q.rail).sort((a,b)=>b.b.min.y-a.b.min.y);// rails: top first
  const D=Math.PI/180;parts.forEach(q=>q.ph=Math.random()*.5);
  /* the cherry trees' bark: same painting, same colour, so the fence looks cut from them */let BUV=null,barkM=null;try{const E2=window.__TREEIM&&(window.__TREEIM.find(e=>!e.GREEN)||window.__TREEIM[0]);const tv=E2&&E2.V&&E2.V.trunk;if(tv&&tv.mat&&tv.mat.map&&tv.geo.attributes.uv){const U=tv.geo.attributes.uv;let u0=1e9,u1=-1e9,v0=1e9,v1=-1e9;for(let i=0;i<U.count;i++){const a=U.getX(i),b2=U.getY(i);u0=Math.min(u0,a);u1=Math.max(u1,a);v0=Math.min(v0,b2);v1=Math.max(v1,b2)}BUV={u0,du:u1-u0,v0,dv:v1-v0};barkM=tv.mat}}catch(e){}
  /* each variant: per piece [tilt in the fence's plane (deg), lean front/back (deg), pivot ('c' centre, 'l'/'r' at a post, 'b' foot of the post), shift x, shift y, height stretch]; null drops the piece */
  const VAR=[
   {posts:[[0,0],[0,0]],rails:[[0],[0]]},
   {posts:[[0,1.5],[0,-1]],rails:[[5,0,'c'],[-2.5,0,'c']]},
   {posts:[[-1.5,0],[2,1]],rails:[[-11,0,'l',.03],[3,0,'c']]},
   {posts:[[0,0],[-7,2.5,'b',0,0,1.06]],rails:[[3.5,0,'l',0,.04],[-1.5,0,'c',-.05]]},
   {posts:[[2.5,-1.5,'b',0,0,1.08],[0,0]],rails:[[-4,0,'c',.06],null]},
   {posts:[[4,1,'b'],[-5,-2,'b',0,0,.96]],rails:[[2,0,'c',.1],[-6,0,'c',-.04,.03]]}];
  const shade=()=>{const r=Math.random();return [.86+r*.22,.84+r*.2,.8+r*.16]};
  const out=[];const v=new V3(),n=new V3();
  for(const VV of VAR){const pos=[],nor=[],uv=[],col=[];
   const add=(q,spec)=>{if(spec===null)return;const [tilt=0,lean=0,pv='c',dx=0,dy=0,hs=1]=spec||[];const c=q.b.getCenter(new V3());let px=c.x,py=c.y;if(pv==='b')py=q.b.min.y;else if(pv==='l'&&posts[0]){px=posts[0].b.getCenter(v).x}else if(pv==='r'&&posts[1]){px=posts[1].b.getCenter(v).x}
    const M=new THREE.Matrix4().makeTranslation(px+dx,py+dy,0).multiply(new THREE.Matrix4().makeRotationZ(tilt*D)).multiply(new THREE.Matrix4().makeRotationX(lean*D)).multiply(new THREE.Matrix4().makeScale(1,hs,1)).multiply(new THREE.Matrix4().makeTranslation(-px,-py,0));const NM=new THREE.Matrix3().getNormalMatrix(M);
    const sh=shade();for(const t of q.tris)for(let cc=0;cc<3;cc++){const i=t*3+cc;v.fromBufferAttribute(P,i).applyMatrix4(M);n.fromBufferAttribute(N,i).applyMatrix3(NM).normalize();pos.push(v.x,v.y,v.z);nor.push(n.x,n.y,n.z);uv.push(UV?UV.getX(i):0,UV?UV.getY(i):0);
     const gnd=1-Math.min(1,Math.max(0,v.y/.22));col.push(sh[0]*(1-gnd*.42),sh[1]*(1-gnd*.22),sh[2]*(1-gnd*.5));
     if(BUV){/* grain along the piece, wrapped round it like bark round a branch */const o=P.getX(i)-c.x,o2=P.getY(i)-c.y,o3=P.getZ(i)-c.z;const L=q.rail?(P.getX(i)-q.b.min.x)/Math.max(.01,q.b.max.x-q.b.min.x):(P.getY(i)-q.b.min.y)/Math.max(.01,q.b.max.y-q.b.min.y);const ang=(Math.atan2(q.rail?o2:o,o3)/6.2832+.5);const ph=q.ph;uv[uv.length-2]=BUV.u0+((ang*.5+ph)%1)*BUV.du;uv[uv.length-1]=BUV.v0+(.1+L*.75)*BUV.dv}}};
   posts.forEach((q,i)=>add(q,VV.posts[i]));rails.forEach((q,i)=>add(q,VV.rails[i]));
   // stand the panel back on the ground after the leaning and stretching
   let lo=1e9;for(let i=1;i<pos.length;i+=3)lo=Math.min(lo,pos[i]);for(let i=1;i<pos.length;i+=3)pos[i]-=lo;
   const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('normal',new THREE.Float32BufferAttribute(nor,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));geo.computeBoundingBox();geo.computeBoundingSphere();geo.userData.src='fence.glb';out.push(geo)}
  const m=(barkM||mat0).clone();m.vertexColors=true;m.metalness=0;m.roughness=1;m.side=THREE.DoubleSide;if(!barkM&&m.color)m.color.multiply(new THREE.Color(1.04,.97,.88));FENCEM=tintMat(m,'fence');FENCEM.userData.tag='fence';return out}
 function archPiece(nm,len){const geo=ARCHGEO[nm];if(!geo)return null;const m=new THREE.Mesh(geo,stoneMat);m.castShadow=m.receiveShadow=true;geo.computeBoundingBox();const b=geo.boundingBox;m.position.set(-(b.min.x+b.max.x)/2,-b.min.y,-(b.min.z+b.max.z)/2);const g=new THREE.Group();g.add(m);g.scale.setScalar(len/Math.max(b.max.x-b.min.x,b.max.z-b.min.z));return g}
 /* plants you place are soft: the cats push through them like the wild ones, only solid things (stones, lanterns, bridges, barrels...) get collision */const SOFTKIND=new Set(['Ghibli bush 1','Ghibli bush 2','Bush','Flowers','Fern','Wheat','Toadstools','Big leaf','Beet patch']);
 E.spawnKind=(k,m)=>spawn(k,m,null);
 function spawn(kind,m,rec){const f=KINDS[kind];if(!f)return null;const o=f();if(!o)return null;const s0=o.scale.clone();m.decompose(o.position,o.quaternion,o.scale);if(!rec)o.scale.multiply(s0);scene.add(o);o.userData.edAdd=rec||{kind,m:null};try{window.__paintPass&&window.__paintPass()}catch(e){}try{LGLOW.scan(o);LGLOW.update(LGLOW.lg)}catch(e){}o.userData.edId='a:'+Math.random().toString(36).slice(2);o.updateMatrixWorld(true);
  /* Build 203: fences settle onto the ground as they're placed: the ground has been reshaped in places since they were set down (the farmhouse yard, the rice paddies), which left some hanging in the air. The posts are sunk a little into the lowest ground under the panel */if(/^Wooden fence/.test(kind)){try{const bb=new THREE.Box3().setFromObject(o),c=bb.getCenter(new V3());const ax=new V3(1,0,0).applyQuaternion(o.quaternion);ax.y=0;ax.normalize();const half=Math.max(.2,(Math.abs(ax.x)>Math.abs(ax.z)?(bb.max.x-bb.min.x):(bb.max.z-bb.min.z))/2-.1);let lo=1e9;for(const t of [-1,-.5,0,.5,1]){const x=c.x+ax.x*half*t,z=c.z+ax.z*half*t;lo=Math.min(lo,heightAt(x,z))}if(lo<1e8){o.position.y+=lo-.07-bb.min.y;o.updateMatrixWorld(true)}}catch(e){}}
  if(o.userData.tree){const p=o.position;const ud=o.userData;const tr={x:p.x,z:p.z,r:ud.trunkR?Math.max(.2,ud.trunkR*o.scale.x):.35*o.scale.x/.5,g:p.y,gl:p.y,climbTop:ud.climbH?p.y+ud.climbH*o.scale.y:-1e9,branches:[]};const sf={t:'trunk',x:p.x,z:p.z,r:ud.trunkR?tr.r+.1:.45,tree:tr};addSurf(sf,p.x-2-tr.r,p.z-2-tr.r,p.x+2+tr.r,p.z+2+tr.r);tr.s0=o.scale.x;tr.r0=tr.r;tr.ct0=tr.climbTop>-1e8?tr.climbTop-p.y:null;o.userData.trunk=tr}else if(!SOFTKIND.has(kind))rebuildSurf(o,null);else o.userData.soft=true;E.objs.push(o);return o}
 // record an edit
 const record=o=>{if(o.userData.edAdd){const a=o.userData.edAdd;o.updateMatrix();a.m=o.matrix.toArray().map(v=>+v.toFixed(4));if(!a.uid)a.uid=newUid();if(!store.adds.includes(a))store.adds.push(a);if(!o.visible)dropAdd(a)}else{store.objs[o.userData.edId]={m:o.matrix.toArray().map(v=>+v.toFixed(4)),del:!o.visible||undefined,rf:o.userData.rockFix?1:undefined}}save()};
 const recordInst=(im,i,m,del)=>{if(im.userData.batch){const b=im.userData.batch;const rec=b.recs[i];if(rec){if(del){dropAdd(rec);dropRec(rec);rebuildBatches()}else rec.m=m.toArray().map(v=>+v.toFixed(4))}save();return}store.objs[im.userData.edId+'#'+i]={m:m.toArray().map(v=>+v.toFixed(4)),del:del||undefined};save()};
 // selection
 let selBox=null;const selMat=new THREE.LineBasicMaterial({color:0xffe07a,depthTest:false,transparent:true,opacity:.9});
 const showBox=()=>{if(selBox){scene.remove(selBox);selBox=null}if(!E.sel)return;if(E.sel.group){const b=new THREE.Box3();for(const it of E.sel.group.items.slice(0,400)){const p=new V3().setFromMatrixPosition(gWorld(it));b.expandByPoint(p)}b.expandByScalar(.4);selBox=new THREE.Box3Helper(b,0xffe07a);selBox.material=selMat;selBox.renderOrder=999;selBox.userData.noEdit=true;scene.add(selBox);return}const t=E.sel.inst?proxy:E.sel.o;let b;if(E.sel.inst){const im=E.sel.inst.im;im.geometry.computeBoundingBox();b=im.geometry.boundingBox.clone().applyMatrix4(proxy.matrixWorld)}else b=new THREE.Box3().setFromObject(t);selBox=new THREE.Box3Helper(b,0xffe07a);selBox.material=selMat;selBox.renderOrder=999;selBox.userData.noEdit=true;scene.add(selBox)};
 /* a group: every piece of one kind, moved / turned / scaled together, each turning and scaling in its own place */
 const gWorld=it=>{if(it.inst){const m=new THREE.Matrix4();it.inst.im.getMatrixAt(it.inst.i,m);return m.premultiply(it.inst.im.matrixWorld)}it.o.updateMatrixWorld(true);return it.o.matrixWorld.clone()};
 const gSet=(it,mw)=>{if(it.inst){setInstQuick(it.inst.im,it.inst.i,mw);return}const o=it.o;const loc=mw.clone();if(o.parent&&o.parent!==scene)loc.premultiply(new THREE.Matrix4().copy(o.parent.matrixWorld).invert());loc.decompose(o.position,o.quaternion,o.scale);o.updateMatrixWorld(true)};
