 const setMode=m=>{if(E.brushOff)E.brushOff();tc.setMode(m);for(const [id,mm] of [['edT','translate'],['edR','rotate'],['edS','scale']])$e(id).setAttribute('aria-pressed',m===mm)};
 $e('edT').onclick=()=>setMode('translate');$e('edR').onclick=()=>setMode('rotate');$e('edS').onclick=()=>setMode('scale');$e('edL').onclick=()=>{tc.setSpace(tc.space==='local'?'world':'local');$e('edL').setAttribute('aria-pressed',tc.space==='local')};
