 const del=()=>{const s=E.sel;if(!s)return;if(s.group){const n=removeKind(s.group.sig,true);select(null);toast('Removed '+n+' pieces',1800);return}if(s.inst){const z=new THREE.Matrix4().makeScale(0,0,0);E.undo.push({inst:{...s.inst},m:s.before.clone()});setInst(s.inst.im,s.inst.i,z);recordInst(s.inst.im,s.inst.i,z,true);const t=treeOf(s.inst.im,s.inst.i);if(!t)instSurf(s.inst.im,s.inst.i,s.before,z);if(t){t.gone=true;for(const sf of SURF)if(sf.tree===t)sf.dead=true}}else{const o=s.o;E.undo.push({o,m:o.matrix.clone(),vis:true});const old=new THREE.Box3().setFromObject(o);o.visible=false;o.userData.gone=true;killSurfIn(old,o);{const t=trunkOf(o);if(t){t.gone=true;t.climbTop=-1e9;for(const sf of SURF)if(sf.tree===t)sf.dead=true}}record(o)}select(null)};
